/**
 * M2 signal core — a PURE TypeScript port of strategies/m2/m2_alert.py's decision logic.
 *
 * The IV-tab M2 panel computes its tile from this, and the 15:45 Telegram alert computes
 * from the Python. Two implementations across a language boundary drift, so this file is
 * held to strategies/m2/parity_fixture.json (generated BY the Python with --emit-fixture)
 * by scripts/m2-parity-check.ts — `npm run selftest:m2`. Change the rules in the Python
 * first, re-emit the fixture, then make this pass. Never the other way round.
 *
 * Exactness notes (each one is a fixture case):
 *   · SMAs are summed left-to-right from 0, the same order as Python's sum(), so the
 *     doubles are bit-identical — the filter test can sit on a knife edge.
 *   · strike uses round-half-to-EVEN (Python round()); Math.round would turn 598.5 into 599.
 *   · Eastern time is computed from the US DST rule, not Intl, matching et_now().
 *   · The IEX quote time is read from QUOTE_TS_FIELDS in that order.
 *
 * No Node imports: safe for the route, the parity script, and (if ever needed) the client.
 */
import calendar from "../../strategies/m2/nyse_calendar.json";

export const SMA_FILTER = 200;
export const SMA_EXIT = 5;
export const MAX_HOLD = 5;
export const STRIKE_MULT = 0.95;
export const STALE_MINUTES = 20;
export const HISTORY_DAYS = 420;
export const QUOTE_TS_FIELDS = ["lastSaleTimeStamp", "lastSaleTimestamp", "timestamp"] as const;

const HOLIDAYS = new Set<string>(calendar.holidays);
const EARLY_CLOSES = new Set<string>(calendar.early_closes);
export const CALENDAR_THROUGH: string = calendar.calendar_through;

export type Bar = [date: string, adjClose: number];

export interface M2State {
  in_trade: boolean;
  entry_date: string | null;
  entry_px?: number | null;
  strike: number | null;
  hold_day: number;
  last_entry_streak_id: string | null;
  [k: string]: unknown;
}

export type AlertKind = "setup" | "enter" | "exit" | "weekly";

export interface LedgerEvent {
  event: "SETUP" | "ENTER" | "EXIT";
  hold_day: number | "";
  strike: number | "";
}

export interface Evaluation {
  kinds: AlertKind[];
  sma200: number;
  sma5: number;
  streak: number;
  filterOn: boolean;
  strike: number;
  state: M2State;
  ledger: LedgerEvent[];
}

// ---------------------------------------------------------------------------
// helpers
// ---------------------------------------------------------------------------

export function roundHalfEven(x: number): number {
  const f = Math.floor(x);
  const diff = x - f;
  if (diff > 0.5) return f + 1;
  if (diff < 0.5) return f;
  return f % 2 === 0 ? f : f + 1;
}

export function lowerCloseStreak(closes: readonly number[]): number {
  let n = 0;
  let i = closes.length - 1;
  while (i > 0 && closes[i] < closes[i - 1]) {
    n += 1;
    i -= 1;
  }
  return n;
}

function sum(xs: readonly number[]): number {
  let s = 0;
  for (const x of xs) s += x;
  return s;
}

const pad = (n: number) => String(n).padStart(2, "0");

function nthSundayUtcMs(year: number, month0: number, n: number): number {
  const first = new Date(Date.UTC(year, month0, 1));
  const offset = (7 - first.getUTCDay()) % 7; // days to the first Sunday
  return Date.UTC(year, month0, 1 + offset + 7 * (n - 1));
}

/** ET wall time as a naive ISO string "YYYY-MM-DDTHH:MM:SS" (et_now() in the Python). */
export function etNowIso(utc: Date = new Date()): string {
  const ms = utc.getTime();
  const y = utc.getUTCFullYear();
  const dstStart = nthSundayUtcMs(y, 2, 2) + 7 * 3600_000;
  const dstEnd = nthSundayUtcMs(y, 10, 1) + 6 * 3600_000;
  const offsetH = ms >= dstStart && ms < dstEnd ? -4 : -5;
  const et = new Date(ms + offsetH * 3600_000);
  return (
    `${et.getUTCFullYear()}-${pad(et.getUTCMonth() + 1)}-${pad(et.getUTCDate())}` +
    `T${pad(et.getUTCHours())}:${pad(et.getUTCMinutes())}:${pad(et.getUTCSeconds())}`
  );
}

export function isSession(dateIso: string): boolean {
  const [y, m, d] = dateIso.split("-").map(Number);
  const dow = new Date(Date.UTC(y, m - 1, d)).getUTCDay(); // 0 Sun .. 6 Sat
  return dow >= 1 && dow <= 5 && !HOLIDAYS.has(dateIso);
}

export function isEarlyClose(dateIso: string): boolean {
  return EARLY_CLOSES.has(dateIso);
}

/** Tiingo ISO stamp → Date. Accepts any fraction length and Z / ±HH:MM; no zone = UTC. */
export function parseTs(ts: string): Date | null {
  const m = /^(\d{4})-(\d\d)-(\d\d)T(\d\d):(\d\d)(?::(\d\d)(\.\d+)?)?(Z|[+-]\d\d:\d\d)?$/.exec(
    ts.trim()
  );
  if (!m) return null;
  const [, y, mo, d, h, mi, s = "0", frac = "", zone = "Z"] = m;
  const ms = frac ? Math.floor(Number(frac.slice(0, 7)) * 1000) : 0; // µs-truncated like Python
  let t = Date.UTC(+y, +mo - 1, +d, +h, +mi, +s, ms);
  if (zone !== "Z") {
    const sign = zone[0] === "-" ? -1 : 1;
    t -= sign * (Number(zone.slice(1, 3)) * 60 + Number(zone.slice(4, 6))) * 60_000;
  }
  return Number.isFinite(t) ? new Date(t) : null;
}

/** One IEX row → { px, etIso }. Mirrors quote_from_row(); throws on the same inputs. */
export function quoteFromRow(q: Record<string, unknown>): { px: number; etIso: string } {
  const px = (q.tngoLast as number | null | undefined) || (q.last as number | null | undefined);
  if (px == null) throw new Error("IEX quote has no tngoLast/last");
  for (const field of QUOTE_TS_FIELDS) {
    const raw = q[field];
    const stamp = raw ? parseTs(String(raw)) : null;
    if (stamp) return { px: Number(px), etIso: etNowIso(stamp) };
  }
  throw new Error("IEX quote has no usable timestamp");
}

/** Sessions after entry, counting today's bar (entry session = day 0). */
export function holdDay(dates: readonly string[], entryDate: string): number {
  return dates.filter((d) => d > entryDate).length;
}

// ---------------------------------------------------------------------------
// the decision — evaluate() in the Python, minus the message text
// ---------------------------------------------------------------------------

export function evaluate(
  history: readonly Bar[],
  px: number,
  today: string,
  state: M2State,
  friday = false
): Evaluation {
  const st: M2State = JSON.parse(JSON.stringify(state));
  const dates = [...history.map((b) => b[0]), today];
  const closes = [...history.map((b) => b[1]), px];
  if (closes.length < SMA_FILTER + 4) {
    throw new Error(`only ${closes.length} closes — need ${SMA_FILTER + 4}`);
  }

  const sma200 = sum(closes.slice(-SMA_FILTER)) / SMA_FILTER;
  const sma5 = sum(closes.slice(-SMA_EXIT)) / SMA_EXIT;
  const streak = lowerCloseStreak(closes);
  const streakId = streak ? dates[dates.length - 1 - streak] : null;
  const filterOn = px > sma200;
  const strike = roundHalfEven(STRIKE_MULT * px);

  const kinds: AlertKind[] = [];
  const ledger: LedgerEvent[] = [];

  if (st.in_trade && st.entry_date) {
    const hold = holdDay(dates, st.entry_date);
    st.hold_day = hold;
    if (hold >= 1) {
      const exit = px > sma5 || hold >= MAX_HOLD;
      if (exit) {
        kinds.push("exit");
        ledger.push({ event: "EXIT", hold_day: hold, strike: st.strike ?? "" });
        Object.assign(st, {
          in_trade: false,
          entry_date: null,
          entry_px: null,
          strike: null,
          hold_day: 0,
          updated_by: "auto:exit",
        });
      }
    }
  } else {
    if (filterOn && streak >= 3 && streakId !== st.last_entry_streak_id) {
      kinds.push("enter");
      ledger.push({ event: "ENTER", hold_day: 0, strike });
      Object.assign(st, {
        in_trade: true,
        entry_date: today,
        entry_px: Math.round(px * 100) / 100,
        strike,
        hold_day: 0,
        last_entry_streak_id: streakId,
        updated_by: "auto:enter",
      });
    } else if (filterOn && streak === 2) {
      kinds.push("setup");
      ledger.push({ event: "SETUP", hold_day: "", strike: "" });
    }
  }

  if (friday) kinds.push("weekly");

  return { kinds, sma200, sma5, streak, filterOn, strike, state: st, ledger };
}
